fn solve(n: i8, m: i8) -> i8 {
    // First, form as many mixed groups as possible.
    // Each mixed group uses 1 unit of the first resource and 2 units of the second.
    // The maximum number of mixed groups is limited by both n and floor(m / 2).
    let mixed = n.min(m / 2);

    // Compute how many units of the second resource remain after forming mixed groups.
    let rem_m = m - 2 * mixed;

    // With the remaining second resource, form pure groups.
    // Each pure group uses 4 units of the second resource.
    let pure = rem_m / 4;

    // Total groups is the sum of mixed and pure groups.
    mixed + pure
}

