        assert_eq!(solve(0, 8), 2);
        assert_eq!(solve(0, 3), 0);
        // Only first resource: no mixed or pure groups
        assert_eq!(solve(5, 0), 0);
        // Mixed groups limited by first resource
        assert_eq!(solve(3, 10), 3); // uses (3*1, 3*2) = (3, 6), rem_m = 4 ⇒ 1 pure ⇒ total = 4
        // Mixed groups limited by second resource
        assert_eq!(solve(10, 5), 2); // uses (2*1, 2*2) = (2, 4), rem_m = 1 ⇒ 0 pure ⇒ total = 2
        // Larger example
        assert_eq!(solve(7, 20), 7.min(20/2) + (20 - 2 * 7.min(20/2)) / 4);
